static int fontAtlasIndex(char c)
{
    const char *p = FONT_CHARS;
    int i = 0;
    while (*p) { if (*p == c) return i; p++; i++; }
    return 36;
}

static void drawGlyphTextured(int x, int y, char c, u32 color, float scale)
{
    int idx = fontAtlasIndex(c);
    int sx = (idx % FONT_COLS) * FONT_CELL_W;
    int sy = (idx / FONT_COLS) * FONT_CELL_H;
    TexVertex *v = (TexVertex *)sceGuGetMemory(2 * sizeof(TexVertex));
    v[0].u = (short)sx; v[0].v = (short)sy; v[0].color = color; v[0].x = (short)x; v[0].y = (short)y; v[0].z = 0;
    v[1].u = (short)(sx + FONT_CELL_W); v[1].v = (short)(sy + FONT_CELL_H); v[1].color = color;
    v[1].x = (short)(x + (int)(FONT_CELL_W * scale)); v[1].y = (short)(y + (int)(FONT_CELL_H * scale)); v[1].z = 0;
    sceGuDrawArray(GU_SPRITES, GU_TEXTURE_32BIT | GU_COLOR_8888 | GU_VERTEX_16BIT | GU_TRANSFORM_2D, 2, NULL, v);
}

static void drawTextSmooth(int x, int y, const char *text, u32 color, float scale, int advance)
{
    int i;
    sceGuEnable(GU_TEXTURE_2D);
    sceGuEnable(GU_BLEND);
    sceGuBlendFunc(GU_ADD, GU_SRC_ALPHA, GU_ONE_MINUS_SRC_ALPHA, 0, 0);
    sceGuTexMode(GU_PSM_8888, 0, 0, 0);
    sceGuTexImage(0, FONT_ATLAS_W, FONT_ATLAS_H, FONT_ATLAS_W, fontAtlas);
    sceGuTexFunc(GU_TFX_MODULATE, GU_TCC_RGBA);
    sceGuTexFilter(GU_LINEAR, GU_LINEAR);
    for (i = 0; text[i]; i++) drawGlyphTextured(x + i * advance, y, text[i], color, scale);
    sceGuDisable(GU_BLEND);
    sceGuDisable(GU_TEXTURE_2D);
}

static void drawText(int x, int y, const char *text, u32 color) { drawTextSmooth(x,y,text,color,0.58f,12); }
static void drawTextSmall(int x, int y, const char *text, u32 color) { drawTextSmooth(x,y,text,color,0.48f,10); }
static void drawTextLarge(int x, int y, const char *text, u32 color) { drawTextSmooth(x,y,text,color,0.76f,16); }

static void drawPlayTriangle(int cx, int cy, int size, u32 color)
{
    Vertex *v = (Vertex *)sceGuGetMemory(3 * sizeof(Vertex));
    v[0].color=color; v[0].x=cx-size/3; v[0].y=cy-size; v[0].z=0;
    v[1].color=color; v[1].x=cx-size/3; v[1].y=cy+size; v[1].z=0;
    v[2].color=color; v[2].x=cx+size; v[2].y=cy; v[2].z=0;
    sceGuDrawArray(GU_TRIANGLES, GU_COLOR_8888|GU_VERTEX_16BIT|GU_TRANSFORM_2D, 3, NULL, v);
}

static void drawIcon(int x,int y,int type,u32 color)
{
    if(type==0){ drawRect(x+3,y+1,14,2,color); drawRect(x+3,y+6,14,2,color); drawRect(x+3,y+11,14,2,color); }
    else if(type==1){ drawRect(x+3,y+3,12,10,color); drawPlayTriangle(x+9,y+8,4,color); }
    else if(type==2){ drawRect(x+4,y+2,3,14,color); drawRect(x+9,y+5,3,11,color); drawRect(x+14,y+1,3,15,color); }
    else if(type==3){ drawBorder(x+2,y+2,15,15,2,color); drawRect(x+6,y+6,7,7,color); }
    else if(type==4){ drawRect(x+3,y+4,14,2,color); drawRect(x+3,y+8,14,2,color); drawRect(x+3,y+12,14,2,color); }
    else { drawRect(x+3,y+3,12,12,color); drawRect(x+6,y,6,18,color); }
}

static void drawMedia(int x,int y,int w,int h,int index)
{
    int idx=index%6, sx=(idx%2)*MEDIA_CELL_W, sy=(idx/2)*MEDIA_CELL_H;
    TexVertex *v=(TexVertex *)sceGuGetMemory(2*sizeof(TexVertex));
    sceGuEnable(GU_TEXTURE_2D); sceGuEnable(GU_BLEND);
    sceGuBlendFunc(GU_ADD,GU_SRC_ALPHA,GU_ONE_MINUS_SRC_ALPHA,0,0);
    sceGuTexMode(GU_PSM_8888,0,0,0); sceGuTexImage(0,MEDIA_ATLAS_W,MEDIA_ATLAS_H,MEDIA_ATLAS_W,mediaAtlas);
    sceGuTexFunc(GU_TFX_REPLACE,GU_TCC_RGBA); sceGuTexFilter(GU_LINEAR,GU_LINEAR);
    v[0].u=sx; v[0].v=sy; v[0].color=COLOR_WHITE; v[0].x=x; v[0].y=y; v[0].z=0;
    v[1].u=sx+240; v[1].v=sy+80; v[1].color=COLOR_WHITE; v[1].x=x+w; v[1].y=y+h; v[1].z=0;
    sceGuDrawArray(GU_SPRITES,GU_TEXTURE_32BIT|GU_COLOR_8888|GU_VERTEX_16BIT|GU_TRANSFORM_2D,2,NULL,v);
    sceGuDisable(GU_BLEND); sceGuDisable(GU_TEXTURE_2D);
}

